'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const KEY='jianwei-village-v1';
const icons={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/>',heart:'<path d="M20.4 4.8a5.2 5.2 0 0 0-7.4 0L12 5.9l-1.1-1.1a5.2 5.2 0 0 0-7.3 7.4L12 21l8.4-8.8a5.2 5.2 0 0 0 0-7.4Z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',leaf:'<path d="M20 3C9 2 2 7 5 15s14 6 15-12Z"/><path d="M3 21 15 9"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h9a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',rain:'<path d="M6 16a5 5 0 0 1-.4-10 6.4 6.4 0 0 1 12 2A4 4 0 0 1 19 16M8 17l-1 4M13 17l-1 4M18 17l-1 4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',car:'<path d="m4 10 2-6h12l2 6M3 10h18v8H3zM5 18v3M19 18v3M6 14h2M16 14h2"/>',train:'<rect x="5" y="3" width="14" height="16" rx="4"/><path d="M5 11h14M8 22l2-3M16 22l-2-3M9 15h.01M15 15h.01M12 3v8"/>',walk:'<circle cx="14" cy="3" r="2"/><path d="m7 9 5-3 3 6 4 2M12 6l-2 8 4 3v5M10 14l-4 7"/>',ticket:'<path d="M3 7h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4V7Z"/><path d="M15 7v2M15 12v2M15 17v2"/>',check:'<path d="m5 12 4 4L20 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chevron:'<path d="m14 5-7 7 7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v16"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-1l-5 2 2-5a9 9 0 1 1 16-5Z"/>',bookmark:'<path d="M6 3h12v19l-6-4-6 4Z"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6L16 3ZM13 6l5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',home:'<path d="m3 10 9-7 9 7v11H3V10ZM9 21v-8h6v8"/>',mountain:'<path d="m2 21 8-16 5 9 3-6 5 13H2ZM7 11l3 2 3-2"/>'};
function icon(n,cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.leaf}</svg>`}
function brandMark(){return '<svg class="brand-mark" viewBox="0 0 48 48" aria-hidden="true"><path d="M4 22 24 8l20 14M10 21v20h28V21M18 41V27h12v14M4 45h40"/><circle cx="36" cy="10" r="4"/></svg>'}
const initialState={favorites:[],saved:[],liked:[],postFavorites:[],posts:[],comments:{},visits:[],prefs:{name:'山野旅行者',origin:'杭州',style:'安静住一晚',strength:'中'}};
let storageUnavailable=false;
function loadState(){try{const data=JSON.parse(localStorage.getItem(KEY)||'null');if(!data||data.version!==1)return clone(initialState);return {...clone(initialState),...data,prefs:{...initialState.prefs,...data.prefs}}}catch(e){storageUnavailable=true;return clone(initialState)}}
let state=loadState();
const ui={filters:{q:'',province:'全部',city:'全部',time:'0',play:'全部',intent:'',sort:'recommend'},communityType:'全部',profileTab:'favorites',plan:null,loading:false,plannerError:'',clarify:null,clarifyCount:0,defaults:[],form:{origin:state.prefs.origin,date:nextWeekend(),days:'2',people:'2',group:'两人同行',transport:'自驾',budget:'650',strength:state.prefs.strength,preference:state.prefs.style,destination:''},prompt:'',modal:null};
function persist(){try{localStorage.setItem(KEY,JSON.stringify({...state,version:1}));return true}catch(e){storageUnavailable=true;toast('浏览器未允许本地存储，当前改动仅在本次页面保留');return false}}
function nextWeekend(){const d=new Date();const add=(6-d.getDay()+7)%7||7;d.setDate(d.getDate()+add);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function formatDate(date){const parts=(date||'').split('-');return parts.length===3?`${Number(parts[1])} 月 ${Number(parts[2])} 日`: '日期待选'}
function displayHours(minutes){return minutes<60?`${minutes} 分钟`:`${Math.floor(minutes/60)} 小时${minutes%60?` ${minutes%60} 分`:''}`}
function getPoi(id){return DESTINATIONS.find(d=>d.id===id)||DESTINATIONS[0]}
function allPosts(){return [...state.posts,...SEED_POSTS]}
function getPost(id){return allPosts().find(p=>p.id===id)}
function photo(name,alt,opts=''){return `<img src="${PHOTO_ASSETS[name]||'assets/'+name+'.jpg'}" alt="${esc(alt)}（氛围示意）" ${opts} decoding="async">`}
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),2900)}
function route(){const raw=(location.hash||'#/discover').slice(1),[path,query]=raw.split('?');return {path,params:new URLSearchParams(query||'')}}
function go(path){if(location.hash==='#'+path){render();window.scrollTo(0,0)}else location.hash=path}
function render(keepScroll=false){const y=window.scrollY;const r=route();const routeChanged=ui.routeKey!==location.hash;ui.routeKey=location.hash;renderHeader(r.path);renderFooter();if(r.path.startsWith('/destination/'))renderDetail(r.path.split('/')[2]);else if(r.path==='/planner'){const planId=r.params.get('plan');if(planId&&ui.loadedId!==planId){const saved=state.saved.find(p=>p.id===planId);if(saved){ui.plan=clone(saved);ui.form={...ui.form,...saved.form};ui.loadedId=planId}}const dest=r.params.get('destination');if(dest&&routeChanged){ui.form.destination=dest;ui.plan=null;ui.loadedId=null}renderPlanner()}else if(r.path==='/community')renderCommunity();else if(r.path==='/my'){if(r.params.get('tab'))ui.profileTab=r.params.get('tab');renderProfile()}else renderDiscover();if(keepScroll)window.scrollTo(0,y)}
function renderHeader(path){const active=path.startsWith('/destination')?'/discover':path;const nav=[['/discover','发现目的地','leaf'],['/planner','行程助手','route'],['/community','旅行广场','chat'],['/my','我的旅行','user']];$('#header').innerHTML=`<div class="wrap header-inner"><a href="#/discover" class="brand" aria-label="见微知乡首页">${brandMark()}<div><span class="brand-name">见微知乡</span><span class="brand-sub">A SLOWER WAY TO TRAVEL</span></div></a><nav class="desktop-nav" aria-label="主导航">${nav.map(([url,label])=>`<a href="#${url}" class="${active===url?'active':''}" ${active===url?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="row header-tools"><label class="origin-select">${icon('pin')}<select data-change="origin" aria-label="出发城市">${['杭州','上海','南京'].map(c=>`<option ${c===state.prefs.origin?'selected':''}>${c}</option>`).join('')}</select></label><a href="#/my?tab=favorites" class="nav-saved" aria-label="想去的目的地，共 ${state.favorites.length} 处">${icon('heart')}${state.favorites.length?`<span>${state.favorites.length}</span>`:''}</a></div></div>`;$('#mobile-nav').innerHTML=nav.map(([url,label,ico])=>`<a href="#${url}" class="${active===url?'active':''}" ${active===url?'aria-current="page"':''}>${icon(ico)}<span>${label==='发现目的地'?'发现':label}</span></a>`).join('')}
function renderFooter(){$('#footer').innerHTML=`<div class="wrap"><div class="footer-inner"><div><a class="brand" href="#/discover">${brandMark()}<span class="brand-name">见微知乡</span></a><p class="footer-phrase">小地方，也值得好好出发。</p><p class="tiny">把周末留给山野，把时间留给日常。</p></div><div class="footer-links"><button data-action="principles">收录原则</button><button data-action="demo-info">演示与隐私说明</button><button data-action="credits">照片来源</button></div></div><p class="footer-note">见微知乡 · 交互演示版　｜　照片为氛围示意；出行时间、价格、路线与内容为样例，出发前请向当地核实。未接入实时模型、天气、营业状态或交易服务。</p></div>`}
function favoriteButton(id){const yes=state.favorites.includes(id);return `<button class="icon-btn ${yes?'active':''}" data-action="favorite" data-id="${id}" aria-label="${yes?'取消收藏':'收藏'}${esc(getPoi(id).name)}" aria-pressed="${yes}">${icon('heart')}</button>`}
function destinationCard(d,i=2){return `<article class="destination-card ${i<2?'lead':''}" data-poi="${d.id}"><div class="card-image"><a href="#/destination/${d.id}" aria-label="了解${d.name}">${photo(d.image,d.name,'loading="lazy"')}</a>${favoriteButton(d.id)}<span class="photo-label">${PHOTO_LABELS[d.image]} · 氛围示意</span></div><div class="card-content"><div class="between"><span class="card-location">${d.province} · ${d.city} · ${d.county}</span><span class="card-duration">${d.days}</span></div><a href="#/destination/${d.id}"><h3 class="card-title">${d.name}</h3><p class="card-description">${d.mood}</p></a><div class="card-meta"><span>${state.prefs.origin}出发 ${displayHours(d.drive[state.prefs.origin])}</span><span>${d.strength==='低'?'轻松慢走':'适度步行'}</span><span>${d.category}</span></div><p class="card-availability">开放与预约待核实 · 出行资料为演示</p><div class="card-reason">${icon('leaf')}<span>${d.reason}</span></div></div></article>`}
function filteredDestinations(){const f=ui.filters;return DESTINATIONS.filter(d=>(!f.q||[d.name,d.city,d.county,d.mood,d.category,d.tags.join('')].join(' ').includes(f.q))&&(f.province==='全部'||d.province===f.province)&&(f.city==='全部'||d.city===f.city)&&(!Number(f.time)||d.drive[state.prefs.origin]<=Number(f.time))&&(f.play==='全部'||d.category===f.play)&&(!f.intent||d.tags.includes(f.intent))).sort((a,b)=>f.sort==='distance'?a.drive[state.prefs.origin]-b.drive[state.prefs.origin]:b.score-a.score)}
function filterSelect(name,label,values){const f=ui.filters;return `<div class="filter-field ${name==='city'?'city-filter':''}"><select aria-label="${label}" data-filter="${name}">${values.map(([value,text])=>`<option value="${value}" ${String(f[name])===String(value)?'selected':''}>${text}</option>`).join('')}</select></div>`}
function renderDiscover(){const f=ui.filters;$('#main').innerHTML=`<div class="demo-line">可交互演示 · 8 处目的地样例 · 收藏与规划仅保存在当前浏览器</div><section class="hero" aria-labelledby="hero-title">${photo('hero','山间村落','class="hero-image" fetchpriority="high"')}<div class="hero-content"><div class="wrap hero-copy"><p class="eyebrow">江浙 · 小而美旅行</p><h1 id="hero-title">找一个适合你的<br>周末目的地</h1><p class="hero-desc">把开放时间、交通、预约和在地体验，<br>一起安排清楚。安心出发，慢慢抵达。</p><a class="button light" href="#/planner">${icon('route')}规划一个周末</a></div></div><div class="hero-aside">Somewhere quiet.<br>Something real.</div><span class="hero-bottom">山间村落摄影 · 氛围示意</span></section><form id="discover-search" class="search-bar"><div class="search-field"><label for="search-query">心里有个地方，或者一种感觉？</label><div class="search-input-row">${icon('search')}<input id="search-query" name="q" value="${esc(f.q)}" placeholder="搜村落、老街、手作或安静" autocomplete="off" maxlength="50"></div></div><div class="search-field search-region"><label for="hero-province">这一站，想去哪</label><select id="hero-province" data-filter="province"><option value="全部">浙江与江苏</option><option ${f.province==='浙江'?'selected':''}>浙江</option><option ${f.province==='江苏'?'selected':''}>江苏</option></select></div><button class="button" type="submit">寻找目的地</button></form><section class="wrap intro"><div class="between"><div><p class="eyebrow">PLACES WITH A LITTLE MORE LIFE</p><h2 class="section-title">小地方，刚刚好的周末</h2><p class="section-copy">去村里住一晚，在老街做一件小东西。<br>按你的同行人、时间和心情，找到舒服的去处。</p></div><span class="tiny">浙江与江苏 · 8 处精选样例</span></div><div class="intents">${[['两天一夜','calendar'],['带爸妈','people'],['手作体验','leaf'],['安静住一晚','moon']].map(([x,i])=>`<button class="intent ${f.intent===x?'active':''}" data-action="intent" data-value="${x}" aria-pressed="${f.intent===x}">${icon(i)}${x}</button>`).join('')}</div></section><section class="wrap catalogue" id="catalogue" aria-label="目的地清单"><div class="filter-bar">${filterSelect('province','按省份筛选',[['全部','全部省份'],['浙江','浙江'],['江苏','江苏']])}${filterSelect('city','按城市筛选',[['全部','全部城市'],...['杭州','湖州','丽水','无锡','苏州','台州'].map(x=>[x,x])])}${filterSelect('time','按驾车时长筛选',[['0','不限车程'],['60','1 小时内'],['120','2 小时内'],['180','3 小时内']])}${filterSelect('play','按玩法筛选',[['全部','全部玩法'],['山野村落','山野村落'],['手作老街','手作老街'],['自然小景','自然小景']])}<button class="filter-clear" data-action="reset-filters">清空筛选</button></div><div id="results"></div></section><section class="editorial"><div class="wrap editorial-grid"><div><p class="eyebrow">A THOUGHTFUL WAY TO GO</p><h2>去哪里之前，<br>先把小事安排好。</h2><p>一条值得信任的行程，从具体的信息开始。少一点不确定，才有多一点心情看风景。</p><a class="button light" href="#/planner">${icon('spark')}试试行程助手</a></div><div><div class="principle">${icon('calendar')}<div><h3>先确认，能不能去</h3><p>开放、预约、停车与返程，和风景一样重要。</p></div></div><div class="principle">${icon('leaf')}<div><h3>说清楚，为什么适合你</h3><p>根据同行人、体力与偏好推荐，留出舒服的节奏。</p></div></div><div class="principle">${icon('rain')}<div><h3>有变化，也有另一个选择</h3><p>给雨天和临时闭店留一个 Plan B，出行更从容。</p></div></div></div></div></section>`;updateResults()}
function updateResults(){const node=$('#results');if(!node)return;const results=filteredDestinations();node.innerHTML=`<div class="between result-bar" aria-live="polite"><span>找到 <strong>${results.length}</strong> 处${ui.filters.intent?` · ${esc(ui.filters.intent)}`:'小而美目的地'}</span><div class="sort"><button data-action="sort" data-value="recommend" class="${ui.filters.sort==='recommend'?'active':''}">综合推荐</button><button data-action="sort" data-value="distance" class="${ui.filters.sort==='distance'?'active':''}">距离优先</button></div></div>${results.length?`<div class="destination-grid">${results.map(destinationCard).join('')}</div>`:emptyState('search','这里还没有合适的去处','试试扩大车程、切换省份，或换一个关键词。','重新看看全部','reset-filters')}`}
function emptyState(ico,title,desc,label,action){return `<div class="empty-state">${icon(ico)}<h3>${title}</h3><p>${desc}</p><button class="button secondary" data-action="${action}">${label}</button></div>`}
function renderDetail(id){const d=DESTINATIONS.find(p=>p.id===id);if(!d){$('#main').innerHTML=`<div class="wrap page-top">${emptyState('pin','没有找到这个目的地','这份演示目前包含 8 处目的地。','返回目的地清单','discover')}</div>`;return}$('#main').innerHTML=`<div class="wrap"><div class="page-top"><a class="back-link" href="#/discover">${icon('chevron')}回到目的地清单</a><div class="between"><div><p class="eyebrow">${d.province} · ${d.city} · ${d.county}</p><h1 class="page-title">${d.name}</h1><p class="page-description">${d.mood} · 建议 ${d.days}</p></div>${favoriteButton(d.id)}</div></div><div class="detail-gallery"><div>${photo(d.image,d.name,'fetchpriority="high"')}<span class="detail-label">${PHOTO_LABELS[d.image]} · 氛围示意，非目的地实景核验</span></div><div class="gallery-side"><div>${photo(d.secondary,'乡野生活','loading="lazy"')}</div><div>${photo(d.id==='shushan'?'pottery':'earth','在地体验','loading="lazy"')}</div></div></div><div class="detail-layout"><div class="detail-body"><section><p class="eyebrow">BEFORE YOU GO</p><h2 style="margin-top:8px">先把出发的事说清楚</h2><div class="detail-facts">${[['ticket','收费',d.fee],['clock','开放',d.hours],['calendar','预约',d.booking],['car','停车与换乘',d.parking],['walk','步行强度',d.walk],['train','最后返程',d.returnTime||'待核实']].map(([i,l,v])=>`<div class="fact">${icon(i)}<div><div class="fact-label">${l}</div><div class="fact-value">${v}</div></div></div>`).join('')}</div><div class="info-note">${icon('info')}<span>以上为演示资料，尚未实地核验；不代表指定日期的实时状态。预约、开放与返程请在出发前向当地确认。</span></div></section><section><h2>这是个什么地方</h2><p>${d.intro}</p></section><section><div class="between"><h2>把时间花在这些小事上</h2><span class="tiny">活动与费用均为演示</span></div>${d.activities.map((a,i)=>`<div class="experience"><div class="experience-time">${['AM','PM','SLOW'][i]}</div><div><h3>${a[0]}</h3><p>${a[1]}</p><span class="tag plain">${a[2]} · ${a[3]}</span></div></div>`).join('')}</section><section><h2>怎么慢慢走</h2><p>${d.walk}。下面是阅读路线，不是实时地图导航。</p><div class="route-list">${[['抵达与休整','先确认停车、换乘及当天开放情况。','预留 20—30 分钟（示例）'],...d.activities.map(a=>[a[0],a[1],a[2]+'（示例）']),['从容返程','给步行、候车或山路留出缓冲时间。',d.returnTime||'末班时间待核实']].map(([a,b,c])=>`<div class="route-stop"><h3>${a}</h3><p>${b}</p><span class="tiny">${c}</span></div>`).join('')}</div></section><section><h2>在日常里，读懂一点地方</h2><p>${d.culture}</p></section><section><h2>先说不好听的</h2><ul class="honest-list">${d.risks.map(x=>`<li>${x}</li>`).join('')}</ul></section><section><div class="row" style="margin-bottom:14px">${icon('rain')}<h2 style="margin:0">下雨，也能换一种过法</h2></div><p>${d.alternatives.join('、')}。替代项同样需要确认开放与预约，遇恶劣天气应优先取消户外活动。</p></section><section><h2>去过之后，留下一个足迹</h2><p>只有你手动确认，才会记录为到访。浏览和规划都不会自动计入。</p><button class="button secondary small" style="margin-top:16px" data-action="visit" data-id="${d.id}">${icon('check')}${state.visits.some(v=>v.poi===d.id)?'查看已记录的足迹':'手动确认到访'}</button></section></div><aside class="sidebar"><p class="eyebrow">YOUR NEXT LITTLE ESCAPE</p><h2 class="sidebar-title">在${d.name}，慢下来</h2><p>${d.tags.slice(0,2).join(' · ')}</p><div class="divider"></div><div class="sidebar-item">${icon('car')}<span>${state.prefs.origin}出发约 ${displayHours(d.drive[state.prefs.origin])}<br><span class="tiny">演示驾车估算</span></span></div><div class="sidebar-item">${icon('walk')}<span>${d.strength==='低'?'低强度慢行':'包含坡道或台阶'}</span></div><div class="sidebar-item">${icon('calendar')}<span>建议停留 ${d.days}</span></div><a class="button" href="#/planner?destination=${d.id}">${icon('route')}规划这趟旅行</a><button class="button secondary" data-action="favorite" data-id="${d.id}">${icon('heart')}${state.favorites.includes(d.id)?'已加入想去':'加入想去'}</button><p class="tiny" style="margin-top:15px">规划与价格为演示；不提供在线预订。</p></aside></div></div><div class="mobile-detail-actions"><button class="button secondary" data-action="favorite" data-id="${d.id}">${icon('heart')}${state.favorites.includes(d.id)?'已加入想去':'加入想去'}</button><a class="button" href="#/planner?destination=${d.id}">${icon('route')}规划这趟旅行</a></div>`}
function optionList(options,value){return options.map(x=>`<option value="${esc(x[0]??x)}" ${(x[0]??x)===String(value)?'selected':''}>${esc(x[1]??x)}</option>`).join('')}
function selectField(name,label,values){return `<div class="form-field"><label for="plan-${name}">${label}</label><select class="form-control" id="plan-${name}" name="${name}">${values.map(x=>{const val=Array.isArray(x)?x[0]:x;const text=Array.isArray(x)?x[1]:x;return `<option value="${esc(val)}" ${String(val)===String(ui.form[name])?'selected':''}>${text}</option>`}).join('')}</select></div>`}
function readForm(){const form=$('#planner-form');if(!form)return;new FormData(form).forEach((v,k)=>{if(k!=='prompt')ui.form[k]=String(v)});ui.prompt=$('#plan-prompt').value}
function renderPlanner(){const f=ui.form;$('#main').innerHTML=`<div class="wrap"><div class="page-top"><p class="eyebrow">MAKE ROOM FOR THE WEEKEND</p><h1 class="page-title">把想法，排成一趟旅行</h1><p class="page-description">说个大概也可以。把路程与休息一起安排，把变化留给备选方案。</p></div><div class="planner-layout"><aside class="planner-input"><h2>这次，想怎么出发？</h2><p class="tiny" style="margin-top:6px">本地规则生成 · 演示规划 · 可保存与编辑</p><form id="planner-form"><div class="form-field full" style="margin-top:18px"><label for="plan-prompt">说说你的想法</label><textarea id="plan-prompt" name="prompt" class="form-control" maxlength="500" placeholder="杭州出发，周末两天，两个人自驾，想住村里，人均六百左右。">${esc(ui.prompt)}</textarea><div class="example-prompts"><button type="button" data-action="example" data-value="couple">两个人住一晚</button><button type="button" data-action="example" data-value="parents">带爸妈慢慢走</button><button type="button" data-action="example" data-value="craft">做一件小东西</button></div><button class="button secondary small" type="button" data-action="parse">${icon('spark')}识别这句话</button></div>${ui.parseSummary?`<div class="parse-recap full">已识别：${esc(ui.parseSummary)}</div>`:''}${ui.clarify?`<div class="clarify full" role="status">${ui.clarify.question}<div class="row">${ui.clarify.options.map(([v,l])=>`<button type="button" data-action="clarify" data-field="${ui.clarify.field}" data-value="${v}">${l}</button>`).join('')}</div><button type="button" class="text-btn" data-action="skip-clarify">按默认条件继续</button></div>`:''}<div class="form-two full">${selectField('origin','从哪里出发',['杭州','上海','南京'])}<div class="form-field"><label for="plan-date">出行日期</label><input class="form-control" id="plan-date" name="date" type="date" required value="${esc(f.date)}"></div></div><div class="form-two full">${selectField('days','旅行天数',[['1','1 天 · 当天往返'],['2','2 天 · 住一晚'],['3','3 天 · 慢一点']])}<div class="form-field"><label for="plan-people">同行人数</label><input class="form-control" id="plan-people" name="people" type="number" min="1" max="6" required value="${esc(f.people)}"></div></div><div class="form-two full">${selectField('group','和谁同行',['两人同行','带爸妈','亲子出行','朋友结伴','一个人'])}${selectField('transport','交通方式',['自驾','高铁 + 当地接驳'])}</div><div class="form-two full"><div class="form-field"><label for="plan-budget">人均预算 / 元</label><input class="form-control" id="plan-budget" name="budget" type="number" min="150" max="10000" required value="${esc(f.budget)}"></div>${selectField('strength','步行强度',[['低','轻松一点'],['中','适度步行'],['高','愿意多走']])}</div>${selectField('preference','更想体验什么',['安静住一晚','手作体验','看山看水','轻松散步'])}${selectField('destination','心里有没有目的地',[['','交给你推荐'],...DESTINATIONS.map(p=>[p.id,p.city+' · '+p.name])])}<div class="full">${ui.plannerError?`<p class="form-error" role="alert">${esc(ui.plannerError)}</p>`:''}<button class="button" type="submit" ${ui.loading?'disabled':''}>${icon('route')}${ui.loading?'正在安排…':'生成我的行程'}</button><p class="tiny" style="margin-top:12px">尚未核实的事实会明确提示，不把未知状态写成“今日开放”。</p></div></form></aside><section id="plan-result" aria-live="polite">${renderPlanResult()}</section></div></div>`}
function renderPlanResult(){if(ui.loading)return `<div class="loading-panel"><div class="spinner" aria-hidden="true"></div><h2>给你的周末，留一点余地</h2><p>正在匹配目的地、分配停留时间与预算…</p><div class="skeleton large"></div><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div></div>`;const p=ui.plan;if(!p)return `<div class="planner-empty"><div class="planner-empty-photo">${photo('earth','江南茶田')}<span class="detail-label">江南茶田 · 氛围示意</span></div><h2>不赶路的周末，<br>从一句想法开始。</h2><p>给一点时间、预算和偏好。我们用 8 处目的地样例，演示一份可以修改、保存的行程。</p><div class="row"><span>${icon('calendar')}1—3 天</span><span>${icon('people')}1—6 人</span><span>${icon('rain')}备选方案</span></div></div>`;const d=getPoi(p.poi),total=budgetTotal(p),localMinutes=p.form.strength==='低'?15:20;return `<div class="plan-cover">${photo(d.image,d.name)}<div class="plan-cover-copy"><span class="eyebrow">${p.rain?'RAINY DAY EDITION':'YOUR SLOW WEEKEND'} · 演示规划</span><h2>${d.name}，${p.rain?'换一种过法':'慢慢过周末'}</h2><p>${d.province} · ${d.city}　｜　${p.form.days} 天${Number(p.form.days)>1?` ${Number(p.form.days)-1} 晚`:''}　｜　${esc(p.form.group)}</p></div></div><div class="plan-summary"><div>出发<strong>${esc(p.form.origin)} · ${formatDate(p.form.date)}</strong></div><div>同行<strong>${p.form.people} 人 · ${esc(p.form.transport)}</strong></div><div>预算估算<strong>¥${total} / 人</strong></div><div>目的地内移动<strong>每日约 ${localMinutes} 分钟</strong></div></div><div class="default-list">${p.source?`行程来源：${esc(p.source)}，已保留署名。<br>`:''}${p.defaults?.length?'默认假设：'+p.defaults.map(esc).join('；')+'。<br>':''}${total>Number(p.form.budget)?`<span class="terra">当前估算超出预算 ¥${total-Number(p.form.budget)} / 人，建议增加预算或缩短天数。</span>`:'预算包含示例交通、餐饮、体验与住宿，不含购物。'}<br>数据尚未实地核实；开放、交通、接驳与体验可预约性均需出发前确认。</div><div class="plan-toolbar"><div class="row"><button class="button small" data-action="save-plan">${icon('bookmark')}${state.saved.some(x=>x.id===p.id)?'更新已保存行程':'保存这份行程'}</button><button class="toggle" data-action="rain" aria-pressed="${p.rain}">${icon(p.rain?'sun':'rain')}${p.rain?'恢复晴天方案':'雨天方案'}</button></div><button class="text-btn" data-action="budget">预算明细</button></div>${p.days.map((day,idx)=>`<section class="plan-day"><div class="plan-day-header"><div><h3>第 ${idx+1} 天 · ${day.theme}</h3><p>${day.subtitle}</p></div>${idx===1?'<button class="text-btn" data-action="edit-second">修改第二天</button>':''}</div>${day.items.map((item,j)=>`<div class="timeline-item ${item.kind==='travel'?'travel':''}"><span class="timeline-time">${item.time}</span><div class="timeline-content"><div class="between"><h4>${esc(item.title)}</h4>${item.kind==='activity'?`<button class="text-btn" data-action="replace" data-day="${idx}" data-index="${j}" aria-label="更换第${idx+1}天${esc(item.title)}">更换</button>`:''}</div><p>${esc(item.desc)}</p><div class="timeline-detail">${icon(item.kind==='travel'?'car':item.kind==='meal'?'clock':'walk')}${esc(item.meta)}</div></div></div>`).join('')}</section>`).join('')}<div class="plan-notes"><h4>出发前，再确认三件事</h4><div>预约：${d.booking}。</div><div>交通：${d.parking}；${d.returnTime||'最后返程时间待核实'}。</div><div>备选：${p.rain?'当前已切换室内优先，仍需逐项确认开放。':d.alternatives.join('、')+'。'}</div></div><div class="row" style="margin-top:18px;flex-wrap:wrap"><button class="button secondary small" data-action="save-plan">${icon('bookmark')}保存到我的旅行</button><a class="button ghost small" href="#/destination/${d.id}">查看目的地资料</a></div>`}
function cnNumber(text){const map={一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9,十:10};return /^\d+$/.test(text)?Number(text):(map[text]||null)}
function parsePrompt(text){const recognized=[];ui.defaults=[];const city=['杭州','上海','南京'].find(c=>text.includes(c));if(city){ui.form.origin=city;recognized.push(city+'出发')}else ui.defaults.push('从表单所选城市出发');const days=text.match(/([一二两三123])\s*[天日]/);if(days){ui.form.days=String(cnNumber(days[1]));recognized.push(ui.form.days+'天')}else if(/住一晚|周末|两天一夜/.test(text)){ui.form.days='2';recognized.push('两天一晚')}else ui.defaults.push('按表单天数安排');const people=text.match(/([一二两三四五六123456])\s*(?:个?人|位)/);if(people){ui.form.people=String(cnNumber(people[1]));recognized.push(ui.form.people+'人')}if(/爸妈|父母|老人|长辈/.test(text)){ui.form.group='带爸妈';ui.form.strength='低';ui.form.preference='轻松散步';if(!people)ui.form.people='3';recognized.push('带爸妈 · 轻松慢走')}else if(/孩子|带娃|亲子/.test(text)){ui.form.group='亲子出行';ui.form.strength='低';if(!people)ui.form.people='3';recognized.push('亲子 · 低强度')}else if(/一个人|独自/.test(text)){ui.form.group='一个人';ui.form.people='1'}if(/自驾|开车/.test(text)){ui.form.transport='自驾';recognized.push('自驾')}else if(/高铁|动车|火车/.test(text)){ui.form.transport='高铁 + 当地接驳';recognized.push('高铁 + 当地接驳')}if(/手作|做壶|陶|非遗|手艺/.test(text)){ui.form.preference='手作体验';recognized.push('手作体验')}else if(/住村|住在村|安静|住一晚/.test(text)){ui.form.preference='安静住一晚';recognized.push('安静住一晚')}else if(/山|水|云|自然/.test(text)&&ui.form.group!=='带爸妈'){ui.form.preference='看山看水';recognized.push('看山看水')}const money=text.match(/(?:人均|每人|预算|一人)\s*(\d{2,5}|[一二三四五六七八九]百(?:[一二三四五六七八九]十)?)\s*(?:元|块|左右)?/);if(money){let val=Number(money[1]);if(!val){const a=money[1].split('百');val=cnNumber(a[0])*100+(a[1]?cnNumber(a[1][0])*10:0)}ui.form.budget=String(Math.min(10000,Math.max(150,val)));recognized.push('人均'+ui.form.budget+'元')}const dest=DESTINATIONS.find(d=>text.includes(d.name));if(dest){ui.form.destination=dest.id;recognized.push(dest.name)}const date=text.match(/(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})/);if(date){const parsed=`${date[1]}-${date[2].padStart(2,'0')}-${date[3].padStart(2,'0')}`;if(!Number.isNaN(new Date(parsed).getTime())){ui.form.date=parsed;recognized.push(formatDate(parsed))}}else ui.defaults.push('出行日期采用表单所选日期');ui.parseSummary=recognized.join(' · ')||'信息比较少，可以直接编辑下面的条件。';if(ui.clarifyCount<2){if(!days&&!/周末|住一晚|两天一夜/.test(text)){ui.clarify={question:'这次打算留几天？',field:'days',options:[['1','当天往返'],['2','住一晚'],['3','慢玩三天']]};ui.clarifyCount++}else if(!/自驾|开车|高铁|动车|火车/.test(text)){ui.clarify={question:'这次怎么过去比较方便？',field:'transport',options:[['自驾','自驾'],['高铁 + 当地接驳','高铁 + 接驳']]};ui.clarifyCount++}else ui.clarify=null}else{ui.clarify=null;ui.defaults.push('未说明的条件采用当前表单设置')}}
function pickDestination(f){if(f.destination)return getPoi(f.destination);let choices=DESTINATIONS.filter(d=>f.strength!=='低'||d.strength==='低');choices=choices.sort((a,b)=>{const score=d=>d.score+(d.tags.includes(f.preference)?22:0)+(f.preference==='手作体验'&&d.category==='手作老街'?20:0)-d.drive[f.origin]/8-(d.cost+d.hotel*(Number(f.days)-1)>Number(f.budget)?20:0);return score(b)-score(a)});return choices[0]}
function hhmm(minutes){return `${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`}
function budgetTotal(p){return p.budget.reduce((sum,b)=>sum+b.amount,0)}
function createPlan(f,source='',defaults=[]){const d=pickDestination(f),days=Number(f.days);const hotel=Number(f.budget)<550?Math.min(d.hotel,150):d.hotel;const budget=[{label:'往返交通',amount:d.transport+(f.transport.startsWith('高铁')?80:0),note:f.transport.startsWith('高铁')?'示例车票与当地接驳估算':'示例燃油、路费与停车分摊'},{label:'餐饮',amount:d.food*days,note:`${days} 天的示例餐费`},{label:'在地体验',amount:d.cost,note:'示例体验与参观费用，需实际询价'},{label:'住宿',amount:hotel*(days-1),note:days>1?`${days-1} 晚示例房费分摊`:'当天往返，无住宿'}];const plan={id:'plan-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),poi:d.id,form:clone(f),rain:false,days:[],budget,source,defaults:clone(defaults),created:new Date().toISOString(),secondRevision:0};buildDays(plan);return plan}
function buildDays(p){const d=getPoi(p.poi),f=p.form,count=Number(f.days),drive=d.drive[f.origin]+(f.transport.startsWith('高铁')?35:0);p.days=[];for(let day=0;day<count;day++){let t=day===0?480+drive:540;const items=[];const add=(time,kind,title,desc,meta)=>items.push({time:hhmm(time),kind,title,desc,meta});if(day===0)add(480,'travel',`${f.origin}出发`,f.transport.startsWith('高铁')?'按演示交通时长安排，车次与当地接驳尚未核实。':'按演示驾车时长安排，实际路况与停车需提前核实。',`跨城抵达约 ${displayHours(drive)}，与目的地内移动分开计算`);add(t,'break',day===0?'抵达，先慢下来':'早餐后，不着急出门',day===0?'核实当天开放情况，办理入住或寄存行李。':'确认今天的体验预约和天气，再决定出发。','休息与缓冲 30 分钟');t+=30;if(t<690){add(t,'meal',day===0?'先吃一顿在地午饭':'一杯热茶，慢慢开始','选择实际营业的餐饮空间，费用以现场为准。','用餐与休息 60 分钟');t+=60}else if(t<840){add(t,'meal','午饭与休息','抵达较晚，先用餐，再开始下午的活动。','用餐与休息 60 分钟');t+=60}const num=count===1?2:(day===count-1?2:2);for(let n=0;n<num;n++){const pool=[...d.activities,['留一段在地日常','在已确认开放的公共空间自由停留','60 分钟','弹性留白'],['随手记下这一程','整理观察与照片，给旅程留一个小结','60 分钟','自主安排'],['再走一段轻松短线','按实际体力选择就近公共路线','60 分钟','出行前核实']];const index=(day*2+n+(day===1?p.secondRevision:0))%pool.length;const act=pool[index];const indoor=[...d.alternatives,'室内阅读与旅途手记','茶歇与照片整理','室内休息与路线复盘'];const title=p.rain?indoor[index]:act[0];add(t,'activity',title,p.rain?'室内或有遮蔽的替代体验；需要另行确认开放与预约。':act[1],`${f.strength==='低'?'轻松版 55':'约 70'} 分钟 · 到达方式与开放需核实`);t+=f.strength==='低'?55:70;if(n<num-1){add(t,'travel','下一站，慢慢过去','在地短途移动，给步行和休息留出余地。',`${f.strength==='低'?'15':'20'} 分钟 · 演示估算`);t+=f.strength==='低'?15:20}if(n===0&&t>=690&&t<810&&day>0){add(t,'meal','午饭，留出休息时间','按同行人口味选择餐饮，提前确认是否营业。','60 分钟');t+=60}}if(day===count-1){add(t+20,'travel','从容返程',`预估 ${hhmm(t+20+drive)} 抵达${f.origin}。这不是实时导航或车次承诺。`,`跨城返程约 ${displayHours(drive)}；实际末班车待核实`)}else add(Math.max(t+30,1050),'meal','晚饭与山间小住','提前向住宿方确认晚饭与次日早餐，夜间以休息为主。','示例住宿费用见预算明细');p.days.push({theme:p.rain?'把时间交给室内':day===0?'抵达，进入慢节奏':day===count-1?'留一点时间，再回程':'多一点在地日常',subtitle:day===0?'跨城路程单列 · 抵达后安排两段体验':'两段体验之间，留出休息与缓冲',items})}}
async function generatePlan(){readForm();ui.plannerError='';if(ui.prompt.trim()&&ui.lastParsedPrompt!==ui.prompt){parsePrompt(ui.prompt);ui.lastParsedPrompt=ui.prompt;if(ui.clarify){renderPlanner();return}}ui.clarify=null;const f=ui.form;const date=new Date(f.date+'T12:00:00');if(!f.date||Number.isNaN(date.getTime()))ui.plannerError='请先选择有效的出行日期。';else if(Number(f.people)<1||Number(f.people)>6)ui.plannerError='这份演示支持 1—6 人同行。';else if(Number(f.budget)<150)ui.plannerError='请填写不少于 150 元的人均演示预算。';else if(f.destination&&f.strength==='低'&&getPoi(f.destination).strength!=='低')ui.plannerError='这个目的地包含坡道或台阶。请切换到适度步行，或选择低强度目的地。';if(ui.plannerError){renderPlanner();return}ui.loading=true;renderPlanner();if(innerWidth<641)$('#plan-result').scrollIntoView({behavior:'smooth',block:'start'});await new Promise(resolve=>setTimeout(resolve,850));ui.plan=createPlan(f,'',ui.defaults);ui.loadedId=null;ui.loading=false;renderPlanner();toast('演示行程已生成，可以继续修改或保存')}
function savePlan(){if(!ui.plan)return;const existing=state.saved.findIndex(p=>p.id===ui.plan.id);const p=clone(ui.plan);p.updated=new Date().toISOString();if(existing>=0)state.saved[existing]=p;else state.saved.unshift(p);const saved=persist();render(true);if(saved)toast(existing>=0?'已更新保存的行程':'已保存到“我的旅行”，刷新后仍可查看')}
function renderCommunity(){const posts=allPosts().filter(p=>ui.communityType==='全部'||p.type===(ui.communityType==='旅行者'?'traveler':'merchant'));$('#main').innerHTML=`<div class="wrap"><div class="page-top community-heading"><div><p class="eyebrow">STORIES ALONG THE WAY</p><div class="between"><h1 class="page-title">旅行广场</h1><button class="button small" data-action="publish">${icon('edit')}写下这一程</button></div><p class="page-description">走过的路、做过的小事，还有村里人的日常。</p></div><p class="community-intro">让一次旅行，<br>成为下一次出发的线索。</p></div><div class="info-note">${icon('info')}<span>下方为演示游记与店铺样例，不是真实评价或商家合作。本地发布的内容仅当前浏览器可见。</span></div><div class="tabs" role="tablist" aria-label="内容类型">${['全部','旅行者','在地店铺'].map(x=>`<button role="tab" aria-selected="${ui.communityType===x}" class="${ui.communityType===x?'active':''}" data-action="community-filter" data-value="${x}">${x==='全部'?'所有故事':x}</button>`).join('')}</div><div class="community-grid">${posts.map(postCard).join('')}</div></div>`}
function postCard(p){const d=getPoi(p.poi),comments=(state.comments[p.id]||[]).length;return `<article class="post-card"><button class="post-image" data-action="post-detail" data-id="${p.id}" aria-label="阅读${esc(p.title)}">${photo(p.image,p.title,'loading="lazy"')}<span class="photo-label">${PHOTO_LABELS[p.image]} · 氛围示意</span></button><div class="post-author"><div class="avatar">${esc(p.avatar)}</div><div><span>${esc(p.author)}</span>${p.type==='merchant'?' <span class="tag warm">店铺样例</span>':''}<small>${esc(p.date)} · ${d.city} ${d.name}</small></div></div><button data-action="post-detail" data-id="${p.id}" style="padding:0;text-align:left"><h2 class="post-title">${esc(p.title)}</h2></button><p class="post-text">${esc(p.text.split('\n')[0])}</p><div class="post-attachment"><div><strong>${p.plan?`${d.name} · ${p.days} 天演示行程`:d.city+' · '+d.name}</strong><small>${p.plan?'来自 @'+esc(p.author)+'，可复制后编辑':'在地体验介绍 · 请核实预约'}</small></div>${p.plan?`<button data-action="copy-post" data-id="${p.id}">复制行程</button>`:`<a class="text-btn" href="#/destination/${p.poi}">看目的地</a>`}</div><div class="post-actions"><button data-action="like-post" data-id="${p.id}" class="${state.liked.includes(p.id)?'active':''}" aria-pressed="${state.liked.includes(p.id)}" aria-label="赞这篇故事">${icon('heart')}<span>${p.likes+(state.liked.includes(p.id)?1:0)}</span></button><button data-action="comments" data-id="${p.id}">${icon('chat')}<span>评论${comments?' '+comments:''}</span></button><button data-action="favorite-post" data-id="${p.id}" class="${state.postFavorites.includes(p.id)?'active':''}" aria-pressed="${state.postFavorites.includes(p.id)}">${icon('bookmark')}<span>${state.postFavorites.includes(p.id)?'已收藏':'收藏'}</span></button></div></article>`}
function renderProfile(){const tabs=[['favorites','想去的地方'],['plans','我的规划'],['posts','我的故事'],['collected','收藏的故事'],['visits','旅行足迹'],['prefs','偏好设置']];if(!tabs.some(x=>x[0]===ui.profileTab))ui.profileTab='favorites';let content='';if(ui.profileTab==='favorites'){const list=DESTINATIONS.filter(d=>state.favorites.includes(d.id));content=list.length?`<div class="destination-grid">${list.map((d,i)=>destinationCard(d,2)).join('')}</div>`:emptyState('heart','下一次出发，从心动开始','把想去的地方收在这里，等一个合适的周末。','发现目的地','discover')}else if(ui.profileTab==='plans')content=state.saved.length?`<div class="saved-grid">${state.saved.map(savedPlanCard).join('')}</div>`:emptyState('route','还没有保存的旅行','说说你的想法，排一份属于自己的周末行程。','开始规划','planner');else if(ui.profileTab==='posts')content=state.posts.length?`<div class="community-grid">${state.posts.map(postCard).join('')}</div>`:emptyState('book','把旅途中的小事写下来','图文和路线可以成为下一次出发的线索。','写一个故事','publish');else if(ui.profileTab==='collected'){const list=allPosts().filter(p=>state.postFavorites.includes(p.id));content=list.length?`<div class="community-grid">${list.map(postCard).join('')}</div>`:emptyState('bookmark','把喜欢的故事收起来','在广场收藏一段经历，慢慢找到旅行灵感。','去旅行广场','community')}else if(ui.profileTab==='visits')content=`<div class="profile-actions"><p class="small subtle">足迹仅记录你手动确认的到访。</p><button class="button secondary small" data-action="visit">${icon('plus')}补记一次旅行</button></div>${state.visits.length?`<div class="visit-list">${state.visits.map(v=>{const d=getPoi(v.poi);return `<article class="visit-row">${photo(d.image,d.name,'loading="lazy"')}<div><h3><a href="#/destination/${d.id}">${d.name}</a></h3><p>${esc(v.date)} · ${esc(v.note||'手动确认到访')}</p></div><button class="icon-btn" aria-label="删除${d.name}足迹" data-action="delete-visit" data-id="${v.id}">${icon('trash')}</button></article>`}).join('')}</div>`:emptyState('pin','旅行足迹，等你慢慢留下','看过页面不会自动成为到访，只有你来确认。','补记一次旅行','visit')}`;else content=`<form id="preference-form" class="preference-panel"><div class="form-field"><label for="pref-name">怎么称呼你</label><input id="pref-name" class="form-control" name="name" value="${esc(state.prefs.name)}" maxlength="16" required></div><div class="form-field"><label for="pref-origin">常用出发城市</label><select id="pref-origin" class="form-control" name="origin">${['杭州','上海','南京'].map(c=>`<option ${state.prefs.origin===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label for="pref-style">喜欢的旅行方式</label><select id="pref-style" class="form-control" name="style">${['安静住一晚','手作体验','看山看水','轻松散步'].map(c=>`<option ${state.prefs.style===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label for="pref-strength">默认步行强度</label><select id="pref-strength" class="form-control" name="strength">${[['低','轻松一点'],['中','适度步行'],['高','愿意多走']].map(([v,l])=>`<option value="${v}" ${state.prefs.strength===v?'selected':''}>${l}</option>`).join('')}</select></div><button class="button" type="submit">保存偏好</button><div class="divider"></div><p class="tiny">数据只保存在当前浏览器，不上传到服务器。</p><button type="button" class="text-btn" data-action="export-data">${icon('download')} 导出我的演示数据</button></form>`;$('#main').innerHTML=`<div class="wrap"><div class="profile-intro"><div class="profile-avatar">${esc(state.prefs.name.slice(0,1))}</div><div><p class="eyebrow">MY LITTLE JOURNEYS</p><h1 class="profile-name" style="margin-top:6px">${esc(state.prefs.name)}</h1><p class="small subtle">${state.prefs.origin}出发 · 让每一个周末，有自己的节奏。</p></div><div class="profile-stats"><div><strong>${state.favorites.length}</strong><span>想去的地方</span></div><div><strong>${state.saved.length}</strong><span>保存的规划</span></div><div><strong>${state.visits.length}</strong><span>确认到访</span></div></div></div><div class="tabs" role="tablist" aria-label="我的旅行分类">${tabs.map(([v,l])=>`<button role="tab" data-action="profile-tab" data-value="${v}" class="${ui.profileTab===v?'active':''}" aria-selected="${ui.profileTab===v}">${l}${v==='posts'&&state.posts.length?' · '+state.posts.length:''}</button>`).join('')}</div><section class="profile-content">${content}</section></div>`}
function savedPlanCard(p){const d=getPoi(p.poi);return `<article class="saved-plan">${photo(d.image,d.name,'loading="lazy"')}<div class="saved-plan-body"><p class="eyebrow">${p.form.origin}出发 · ${formatDate(p.form.date)}</p><h3>${d.name} · ${p.form.days} 天</h3><p>${p.form.people} 人 · 人均 ¥${budgetTotal(p)} · ${p.rain?'雨天版':'演示规划'}</p>${p.source?`<p>来自 @${esc(p.source)}</p>`:''}<div class="row"><a class="button secondary small" href="#/planner?plan=${p.id}">${icon('edit')}查看与编辑</a><button class="icon-btn" data-action="delete-plan" data-id="${p.id}" aria-label="删除${d.name}规划">${icon('trash')}</button></div></div></article>`}
let previousFocus=null;
function modal(title,content,wide=false){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop="true"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div>${content}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal button,.modal input,.modal select')?.focus())}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';ui.modal=null;if(previousFocus?.isConnected)previousFocus.focus()}
function confirmDelete(message,action,id){modal('确认删除',`<p>${message}删除仅影响当前浏览器中保存的演示数据。</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">保留</button><button class="button danger" data-action="${action}" data-id="${id}">确认删除</button></div>`)}
function showBudget(){const p=ui.plan;if(!p)return;modal('这一趟，预算怎么分',`<p>${p.form.people} 人同行 · 以下为每人估算，金额仅供演示。</p><table class="budget-table"><thead><tr><th scope="col">项目</th><th scope="col">人均 / 元</th></tr></thead><tbody>${p.budget.map(b=>`<tr><td>${b.label}<br><span class="tiny">${b.note}</span></td><td>¥${b.amount}</td></tr>`).join('')}</tbody><tfoot><tr><td>人均合计</td><td>¥${budgetTotal(p)}</td></tr><tr><td>${p.form.people} 人合计</td><td>¥${budgetTotal(p)*Number(p.form.people)}</td></tr></tfoot></table><div class="info-note">${icon('info')}<span>不含购物与临时加购；并非实时价格，不提供预订或支付。请向实际服务方询价。</span></div>`)}
function showReplacement(day,index){const p=ui.plan;if(!p)return;const d=getPoi(p.poi);modal('换一种停留方式',`<p>保留第 ${day+1} 天的时间框架，只更换这一个体验。以下均为演示选项，需要确认开放与预约。</p><div class="stack" style="margin-top:20px">${[...d.activities.map(a=>({title:a[0],desc:a[1]})),...d.alternatives.map(t=>({title:t,desc:'室内或有遮蔽的替代体验，需提前确认。'}))].filter(a=>a.title!==p.days[day].items[index].title).map(a=>`<button class="post-attachment" style="text-align:left;margin:0" data-action="choose-replacement" data-day="${day}" data-index="${index}" data-title="${esc(a.title)}" data-desc="${esc(a.desc)}"><div><strong>${a.title}</strong><small>${a.desc}</small></div>${icon('plus')}</button>`).join('')}</div>`)}
function showComments(id){const p=getPost(id);if(!p)return;ui.modal={type:'comments',id};modal('这一程的留言',`<p>${esc(p.title)} · 评论仅保存在当前浏览器。</p><div id="comment-list">${(state.comments[id]||[]).length?(state.comments[id]||[]).map(c=>`<div class="comment-row"><strong>${esc(c.author)}</strong><p>${esc(c.text)}</p></div>`).join(''):'<div class="empty-state" style="margin-top:18px;padding:30px 15px"><p style="margin:0">还没有留言，说说你的旅行想法吧。</p></div>'}</div><form id="comment-form" class="comment-form" data-post="${id}"><input name="comment" aria-label="评论内容" class="form-control" placeholder="留下一个想法…" maxlength="200" required><button class="button small" type="submit">发布留言</button></form>`)}
function showPost(id){const p=getPost(id);if(!p)return;const d=getPoi(p.poi);modal(esc(p.title),`${photo(p.image,p.title,'class="post-detail-photo"')}<p class="tiny">${esc(p.author)} · ${esc(p.date)} · 图片为氛围示意</p><div style="margin-top:18px">${p.text.split('\n').filter(Boolean).map(t=>`<p style="margin-bottom:16px">${esc(t)}</p>`).join('')}</div><div class="post-attachment"><div><strong>${d.city} · ${d.name}</strong><small>${p.plan?'演示行程，可复制后自行调整':'店铺样例，不代表真实合作'}</small></div>${p.plan?`<button data-action="copy-post" data-id="${id}">复制行程</button>`:`<button data-action="detail-from-modal" data-id="${d.id}">看目的地</button>`}</div>`,true)}
function publishForm(){ui.postDraft=ui.postDraft||{title:'',text:'',poi:'chenjiapu',type:'traveler'};const d=ui.postDraft;modal('写下这一程',`<p>发布后仅当前浏览器可见。所有新内容显示为“本地演示”，不会上传到社区。</p><form id="publish-form" style="margin-top:20px"><div class="form-field"><label for="post-title">故事标题</label><input class="form-control" id="post-title" name="title" maxlength="40" minlength="4" required value="${esc(d.title)}" placeholder="写一个具体的小发现"></div><div class="form-field"><label for="post-text">旅途中的小事</label><textarea class="form-control" id="post-text" name="text" maxlength="1500" minlength="20" required placeholder="描述你的路线、体验和实用提醒，至少 20 字。">${esc(d.text)}</textarea></div><div class="form-two"><div class="form-field"><label for="post-poi">关联目的地</label><select class="form-control" id="post-poi" name="poi">${DESTINATIONS.map(x=>`<option value="${x.id}" ${d.poi===x.id?'selected':''}>${x.city} · ${x.name}</option>`).join('')}</select></div><div class="form-field"><label for="post-type">发布身份</label><select class="form-control" id="post-type" name="type"><option value="traveler" ${d.type==='traveler'?'selected':''}>旅行者 · 附演示行程</option><option value="merchant" ${d.type==='merchant'?'selected':''}>在地店铺 · 样例</option></select></div></div><p class="tiny">使用关联目的地的授权氛围照片，不上传个人照片。店铺样例仅附目的地，不附用户行程。</p><p id="publish-error" class="form-error" role="alert"></p><div class="modal-actions"><button class="button secondary" type="submit" name="mode" value="preview">预览故事</button><button class="button" type="submit" name="mode" value="publish">发布到本地</button></div><div id="post-preview"></div></form>`,true)}
function visitModal(id){const old=id&&state.visits.find(v=>v.poi===id);if(old){go('/my?tab=visits');toast('这次到访已经记录在旅行足迹里');return}modal('补记一次旅行',`<p>请只记录实际到访。这里不会读取定位或自动识别行程。</p><form id="visit-form" style="margin-top:20px"><div class="form-field"><label for="visit-poi">去过的地方</label><select class="form-control" id="visit-poi" name="poi">${DESTINATIONS.map(d=>`<option value="${d.id}" ${d.id===id?'selected':''}>${d.city} · ${d.name}</option>`).join('')}</select></div><div class="form-field"><label for="visit-date">到访日期</label><input class="form-control" type="date" id="visit-date" name="date" max="${new Date().toLocaleDateString('sv-SE')}" value="${new Date().toLocaleDateString('sv-SE')}" required></div><div class="form-field"><label for="visit-note">留一句小记</label><input class="form-control" id="visit-note" name="note" maxlength="80" placeholder="那天做了一件什么小事？"></div><button class="button" type="submit">确认实际到访</button></form>`)}
function toggleIn(arr,value){const i=arr.indexOf(value);if(i>=0)arr.splice(i,1);else arr.push(value)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b){if(e.target.dataset.backdrop)closeModal();return}e.preventDefault();const {action,id,value}=b.dataset;switch(action){
 case 'favorite':toggleIn(state.favorites,id);persist();render(true);break;
 case 'intent':ui.filters.intent=ui.filters.intent===value?'':value;render(true);break;
 case 'sort':ui.filters.sort=value;updateResults();break;
 case 'reset-filters':ui.filters={q:'',province:'全部',city:'全部',time:'0',play:'全部',intent:'',sort:'recommend'};render(true);break;
 case 'discover':go('/discover');break;case 'planner':go('/planner');break;case 'community':go('/community');break;
 case 'close-modal':closeModal();break;
 case 'parse':readForm();if(!ui.prompt.trim()){ui.plannerError='先写一句旅行想法，或点击一个示例。';renderPlanner();break}ui.plannerError='';parsePrompt(ui.prompt);ui.lastParsedPrompt=ui.prompt;renderPlanner();break;
 case 'example':readForm();ui.form.destination='';ui.prompt=value==='parents'?'上海出发，一天，带爸妈，三个人自驾，少走路，人均三百元。':value==='craft'?'南京出发，一天，两个人坐高铁，想体验陶艺手作，人均五百元。':'杭州出发，周末两天，两个人自驾，想安静住村里，人均六百元。';ui.clarifyCount=0;parsePrompt(ui.prompt);ui.lastParsedPrompt=ui.prompt;renderPlanner();break;
 case 'clarify':readForm();ui.form[b.dataset.field]=value;ui.clarify=null;ui.parseSummary=(ui.parseSummary||'')+' · '+value;renderPlanner();break;
 case 'skip-clarify':readForm();ui.defaults.push('未补充项采用表单默认设置');ui.clarify=null;renderPlanner();break;
 case 'save-plan':savePlan();break;
 case 'rain':if(ui.plan){ui.plan.rain=!ui.plan.rain;buildDays(ui.plan);render(true);toast(ui.plan.rain?'已切换室内优先的演示方案，请核实开放':'已恢复晴天方案')}break;
 case 'budget':showBudget();break;
 case 'replace':showReplacement(Number(b.dataset.day),Number(b.dataset.index));break;
 case 'choose-replacement':if(ui.plan){const item=ui.plan.days[Number(b.dataset.day)].items[Number(b.dataset.index)];item.title=b.dataset.title;item.desc=b.dataset.desc;closeModal();render(true);toast('已更换这个体验，时间框架保持不变')}break;
 case 'edit-second':if(ui.plan?.days[1]){ui.plan.secondRevision++;const old=clone(ui.plan.days);buildDays(ui.plan);ui.plan.days=ui.plan.days.map((day,i)=>i===1?day:old[i]);render(true);toast('已调整第二天，第一天保持原样')}break;
 case 'community-filter':ui.communityType=value;render(true);break;
 case 'like-post':toggleIn(state.liked,id);persist();render(true);break;
 case 'favorite-post':toggleIn(state.postFavorites,id);persist();render(true);break;
 case 'comments':showComments(id);break;case 'post-detail':showPost(id);break;
 case 'detail-from-modal':closeModal();go('/destination/'+id);break;
 case 'copy-post':{const post=getPost(id);if(!post)break;const f={...ui.form,destination:post.poi,days:String(post.days),origin:state.prefs.origin,date:nextWeekend(),group:'两人同行',people:'2',strength:getPoi(post.poi).strength};const plan=createPlan(f,post.author,['按当前出发城市与下个周末重新生成']);state.saved.unshift(clone(plan));persist();ui.plan=plan;ui.form=clone(f);ui.loadedId=plan.id;closeModal();go('/planner?plan='+plan.id);toast('已复制并保存，保留原作者署名，可继续编辑');break}
 case 'publish':publishForm();break;
 case 'profile-tab':ui.profileTab=value;history.replaceState(null,'','#/my');render(true);break;
 case 'delete-plan':confirmDelete('这份规划将从“我的旅行”移除。','confirm-delete-plan',id);break;
 case 'confirm-delete-plan':state.saved=state.saved.filter(p=>p.id!==id);persist();closeModal();render(true);toast('已删除这份规划');break;
 case 'visit':visitModal(id);break;
 case 'delete-visit':confirmDelete('这条手动足迹将被移除。','confirm-delete-visit',id);break;
 case 'confirm-delete-visit':state.visits=state.visits.filter(v=>v.id!==id);persist();closeModal();render(true);break;
 case 'export-data':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='见微知乡_我的演示数据.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已导出当前浏览器中的演示数据');break}
 case 'principles':modal('为什么收录这些地方',`<div class="stack"><p>这份演示从村落、手作老街与自然小景中，选择适合短途停留的目的地样例。我们希望先说清楚适合谁、怎么去、有什么限制。</p><p><strong>情境匹配：</strong>综合考虑同行结构、时间、体力和体验偏好。</p><p><strong>可执行信息：</strong>展示预约、交通与返程的确认要求；未知字段明确标注待核实。</p><p><strong>独立推荐：</strong>这份演示没有付费排序与真实商业套餐，推荐不受佣金影响。</p><p><strong>诚实表达：</strong>照片为授权氛围素材，不是已核验的目的地实景；所有示例信息需要实际核对。</p></div>`);break;
 case 'demo-info':modal('演示与隐私说明',`<div class="stack"><p>这是“见微知乡”的前端交互演示。规划由本地样例数据与规则生成，未接入实时大模型、天气、地图、营业状态或交易接口。</p><p>收藏、点赞、评论、规划、足迹与偏好通过 localStorage 保存在当前浏览器。不会采集位置、手机号、连续轨迹，也不会将发布内容上传到社区。</p><p>清理浏览器数据或更换设备后，这些本地记录不会同步。你可以在“我的旅行—偏好设置”导出数据。</p><p>地名是真实名称；车程、费用、活动与故事为演示样例，不能作为出行承诺。重要信息缺失时会显示“待核实”。</p></div>`);break;
 case 'credits':modal('摄影，让乡野被看见',`<p style="margin-bottom:20px">照片来自 Pexels，按其摄影许可使用。以下素材统一作为氛围示意，不代表所列目的地，也不代表摄影师或店铺为项目背书。</p><div class="credits">${PHOTO_CREDITS.photos.map(p=>`<div class="credit-item"><strong>${esc(PHOTO_LABELS[p.file.replace('.jpg','')])}</strong> · ${esc(p.author)}<br><a href="${esc(p.source_url)}" target="_blank" rel="noopener noreferrer">查看摄影原作</a> · <a href="https://www.pexels.com/license/" target="_blank" rel="noopener noreferrer">Pexels License</a></div>`).join('')}</div>`);break;
}});
document.addEventListener('change',e=>{const field=e.target.dataset.filter;if(field){ui.filters[field]=e.target.value;if(field==='province')ui.filters.city='全部';render(true);return}if(e.target.dataset.change==='origin'){state.prefs.origin=e.target.value;ui.form.origin=e.target.value;persist();render(true);return}if(e.target.closest('#planner-form')){readForm();ui.plannerError=''}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search-query'){clearTimeout(searchTimer);ui.filters.q=e.target.value.trim();searchTimer=setTimeout(updateResults,150)}});
document.addEventListener('submit',e=>{const form=e.target;if(!['discover-search','planner-form','comment-form','publish-form','visit-form','preference-form'].includes(form.id))return;e.preventDefault();const fd=new FormData(form);switch(form.id){
 case 'discover-search':ui.filters.q=String(fd.get('q')||'').trim();updateResults();$('#catalogue').scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'planner-form':generatePlan();break;
 case 'comment-form':{const text=String(fd.get('comment')||'').trim();if(!text)return;const id=form.dataset.post;state.comments[id]=state.comments[id]||[];state.comments[id].push({author:state.prefs.name,text,date:new Date().toISOString()});persist();render(true);showComments(id);toast('留言已保存在当前浏览器');break}
 case 'publish-form':{const title=String(fd.get('title')||'').trim(),text=String(fd.get('text')||'').trim(),poi=String(fd.get('poi')),type=String(fd.get('type'));ui.postDraft={title,text,poi,type};if(title.length<4||text.length<20){$('#publish-error').textContent='标题至少 4 字，正文至少 20 字。';return}if(e.submitter?.value==='preview'){$('#post-preview').innerHTML=`<article class="preview-post"><span class="tag">本地演示预览</span><h3 style="margin-top:12px">${esc(title)}</h3><p>${esc(text).replace(/\n/g,'<br>')}</p><p class="tiny" style="margin-top:12px">${getPoi(poi).name} · ${type==='merchant'?'店铺样例':'旅行者 · 附演示行程'}</p></article>`;return}const d=getPoi(poi);state.posts.unshift({id:'local-'+Date.now(),author:state.prefs.name,type,avatar:state.prefs.name[0],title,text,poi,image:d.image,days:d.duration,likes:0,baseComments:[],date:'本地演示 · 刚刚',plan:type==='traveler'});persist();ui.postDraft=null;closeModal();ui.communityType='全部';go('/community');render();toast('故事已发布到本地演示广场');break}
 case 'visit-form':{const poi=String(fd.get('poi')),date=String(fd.get('date'));const old=state.visits.find(v=>v.poi===poi&&v.date===date);if(old){toast('这一天的到访已经记录过了');return}state.visits.unshift({id:'visit-'+Date.now(),poi,date,note:String(fd.get('note')||'').trim()});persist();closeModal();ui.profileTab='visits';go('/my?tab=visits');render();toast('已记录这次手动确认的到访');break}
 case 'preference-form':state.prefs={name:String(fd.get('name')).trim()||'山野旅行者',origin:String(fd.get('origin')),style:String(fd.get('style')),strength:String(fd.get('strength'))};ui.form.origin=state.prefs.origin;ui.form.preference=state.prefs.style;ui.form.strength=state.prefs.strength;persist();render(true);toast('已保存你的旅行偏好');break;
}});
document.addEventListener('keydown',e=>{const modalNode=$('.modal');if(!modalNode)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const nodes=$$('button,a,input,select,textarea,[tabindex="0"]',modalNode).filter(n=>!n.disabled&&n.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){const img=e.target;const fallback=document.createElement('div');fallback.className='img-fallback';fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt+'；图片暂不可用');fallback.textContent='乡野，留一点想象';img.replaceWith(fallback)}},true);
window.addEventListener('hashchange',()=>{if(ui.modal||$('.modal'))closeModal();render();window.scrollTo({top:0,behavior:'instant'})});
render();
if(storageUnavailable)setTimeout(()=>toast('当前浏览器限制本地存储，改动可能无法跨刷新保留'),600);
